inline void SaveTilingBytes(const void* src, uint32_t bytes, uint32_t* dstU32, uint32_t maxU32)
{
    uint32_t words = (bytes + 3) / 4;
    if (words > maxU32) {
        words = maxU32;
    }
    const uint32_t* p = reinterpret_cast<const uint32_t*>(src);
    for (uint32_t i = 0; i < words; ++i) {
        dstU32[i] = p[i];
    }
}
